SELECT COALESCE(SUM(amount), 0) AS ingresos_por_compras_dlc_2025
FROM purchase
WHERE purchase_date BETWEEN DATE '2025-01-01' AND DATE '2025-12-31';

SELECT c.is_active, c.founded_year, c.country, c.name, c.company_id
FROM company c
WHERE EXISTS (
  SELECT 1 FROM game g WHERE g.publisher_company_id = c.company_id
)
AND NOT EXISTS (
  SELECT 1 FROM game g2 WHERE g2.developer_company_id = c.company_id
)
ORDER BY c.name;

SELECT ROUND(100.0 * SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 2) AS porcentaje_activas
FROM subscription
WHERE start_date >= DATE '2024-01-01' AND start_date < DATE '2025-01-01';

SELECT plan_id, name, monthly_price
FROM subscription_plan
ORDER BY monthly_price;

SELECT game.game_id, game.title, game.franchise_id, franchise.name
FROM game
JOIN franchise ON game.franchise_id = franchise.franchise_id;

SELECT game.title, franchise.name
FROM game
JOIN franchise ON game.franchise_id = franchise.franchise_id;

SELECT DISTINCT game_id
FROM tournament
WHERE prize_pool > 10000;

SELECT name, monthly_price
FROM subscription_plan
ORDER BY name ASC;

